64	/// `POST /collections/{collection}/records`：提交一批记录（全有或全无）。
65	async fn write_records(
66	    State(s): State<Arc<Store>>,
67	    Path(collection): Path<String>,
68	    payload: Result<Json<WriteRequest>, axum::extract::rejection::JsonRejection>,
69	) -> Result<Json<Value>, ApiError> {
70	    let Json(req) = payload.map_err(|e| ApiError::new(StatusCode::BAD_REQUEST, e.body_text()))?;
71	    if req.records.is_empty() {
72	        return Err(ApiError::new(
73	            StatusCode::BAD_REQUEST,
74	            "records must be a non-empty array",
75	        ));
76	    }
77	    match s.write_batch(&collection, &req.records) {
78	        Ok(out) => Ok(Json(json!({
79	            "collection": out.collection,
80	            "accepted": out.accepted,
81	            "inserted": out.inserted,
82	        }))),
83	        Err(BatchError::Rejected(r)) => Err(ApiError {
84	            status: StatusCode::BAD_REQUEST,
85	            body: json!({
86	                "error": r.reason,
87	                "index": r.index,
88	                "id": r.id,
89	            }),
90	        }),
91	        Err(BatchError::Persist(msg)) => Err(ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, msg)),
92	    }
93	}
