134	/// `GET /versions/{id}/collections/{collection}/records`：查询版本内集合的全部记录。
135	async fn read_records(
136	    State(s): State<Arc<Store>>,
137	    Path((version_id, collection)): Path<(u64, String)>,
138	) -> Result<Json<Value>, ApiError> {
139	    let records = s
140	        .read_records(version_id, &collection)
141	        .map_err(|e| lookup_error(e, &collection, version_id))?;
142	    Ok(Json(json!({
143	        "version": version_id,
144	        "collection": collection,
145	        "records": records,
146	    })))
147	}
