149	/// `GET /versions/{from}/collections/{collection}/diff/{to}`：
150	/// 比较同一集合在两个已保存版本之间的差异（只读，不生成新版本）。
151	async fn diff_versions(
152	    State(s): State<Arc<Store>>,
153	    Path((from, collection, to)): Path<(u64, String, u64)>,
154	) -> Result<Json<Value>, ApiError> {
155	    let d = s
156	        .diff_versions(from, to, &collection)
157	        .map_err(|e| diff_error(e, &collection, from, to))?;
158	    let changed: Vec<Value> = d
159	        .changed
160	        .iter()
161	        .map(|c| {
162	            json!({
163	                "id": c.before["id"],
164	                "before": c.before,
165	                "after": c.after,
166	            })
167	        })
168	        .collect();
169	    Ok(Json(json!({
170	        "from": d.from,
171	        "to": d.to,
172	        "collection": d.collection,
173	        "added": d.added,
174	        "dropped": d.dropped,
175	        "changed": changed,
176	    })))
177	}
178	
179	/// 差异查询的错误映射：版本/集合不存在为 404，起始版本晚于目标版本为 400。
180	fn diff_error(e: DiffError, collection: &str, from: u64, to: u64) -> ApiError {
181	    match e {
182	        DiffError::FromVersionNotFound => {
183	            ApiError::new(StatusCode::NOT_FOUND, format!("version {from} not found"))
184	        }
185	        DiffError::ToVersionNotFound => {
186	            ApiError::new(StatusCode::NOT_FOUND, format!("version {to} not found"))
187	        }
188	        DiffError::CollectionNotFoundInFrom => ApiError::new(
189	            StatusCode::NOT_FOUND,
190	            format!("collection \"{collection}\" not found in version {from}"),
191	        ),
192	        DiffError::CollectionNotFoundInTo => ApiError::new(
193	            StatusCode::NOT_FOUND,
194	            format!("collection \"{collection}\" not found in version {to}"),
195	        ),
196	        DiffError::OutOfOrder => ApiError::new(
197	            StatusCode::BAD_REQUEST,
198	            format!("start version {from} is later than target version {to}"),
199	        ),
200	    }
201	}
202	
203	/// 便于组合状态码与响应体。
204	fn lookup_error(e: LookupError, collection: &str, version: u64) -> ApiError {
205	    match e {
206	        LookupError::VersionNotFound => ApiError::new(
207	            StatusCode::NOT_FOUND,
208	            format!("version {version} not found"),
209	        ),
210	        LookupError::CollectionNotFound => ApiError::new(
211	            StatusCode::NOT_FOUND,
212	            format!("collection \"{collection}\" not found in version {version}"),
213	        ),
