502	/// WAL 重放/应用：按主键 upsert；整批来自同一个 commit 事件。
503	fn apply_commit(
504	    current: &mut BTreeMap<String, Vec<Record>>,
505	    collection: String,
506	    records: Vec<Record>,
507	) {
508	    let entry = current.entry(collection).or_default();
509	    for rec in records {
510	        let id = rec["id"].as_str().expect("validated commit");
511	        match entry.iter().position(|r| r["id"] == id) {
512	            Some(pos) => entry[pos] = rec,
513	            None => entry.push(rec),
514	        }
515	    }
516	}
