527	/// 完整状态写入 snapshot.json（临时文件 + fsync + 原子重命名 + 目录 fsync）。
528	fn persist_state(dir: &Path, st: &Inner) -> Result<(), String> {
529	    let state = PersistedState {
530	        versions: st
531	            .versions
532	            .iter()
533	            .map(|v| PersistedVersion {
534	                id: v.id,
535	                saved_at: v.saved_at,
536	                collections: v
537	                    .data
538	                    .iter()
539	                    .map(|(name, records)| PersistedCollection {
540	                        name: name.clone(),
541	                        records: records.clone(),
542	                    })
543	                    .collect(),
544	            })
545	            .collect(),
546	        collections: st
547	            .current
548	            .iter()
549	            .map(|(name, records)| PersistedCollection {
550	                name: name.clone(),
551	                records: records.clone(),
552	            })
553	            .collect(),
554	    };
555	    let mut bytes = serde_json::to_vec(&state).map_err(|e| format!("encode snapshot: {e}"))?;
556	    bytes.push(b'\n');
557	
558	    let target = dir.join("snapshot.json");
559	    let tmp = dir.join("snapshot.json.tmp");
560	    {
561	        let mut f = fs::OpenOptions::new()
562	            .create(true)
563	            .write(true)
564	            .truncate(true)
565	            .open(&tmp)
566	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
567	        f.write_all(&bytes)
568	            .and_then(|_| f.flush())
569	            .and_then(|_| f.sync_all())
570	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
571	    }
572	    fs::rename(&tmp, &target).map_err(|e| format!("rename snapshot: {e}"))?;
573	    if let Ok(d) = fs::File::open(dir) {
574	        let _ = d.sync_all();
575	    }
576	    Ok(())
577	}
578	
579	/// 清空 WAL（其中的提交已固化进 snapshot.json），并重新以追加模式打开。
580	fn truncate_wal(wal: &mut fs::File, wal_path: &Path) -> Result<(), String> {
581	    {
582	        let mut f = fs::OpenOptions::new()
583	            .create(true)
584	            .write(true)
585	            .truncate(true)
586	            .open(wal_path)
587	            .map_err(|e| format!("truncate wal: {e}"))?;
588	        f.flush()
589	            .and_then(|_| f.sync_all())
590	            .map_err(|e| format!("truncate wal: {e}"))?;
591	    }
592	    // 先关闭旧句柄，再以 append 重新打开供后续提交使用。
593	    let reopened = fs::OpenOptions::new()
594	        .append(true)
595	        .open(wal_path)
596	        .map_err(|e| format!("reopen wal: {e}"))?;
597	    *wal = reopened;
598	    Ok(())
599	}
