        .iter()
        .find(|rec| rec["id"] == "u1")
        .unwrap()
        .clone();
    assert_eq!(u1["v"], 1);

    // 当前数据与替换后一致。
    let v2 = request(&addr, "POST", "/versions", None)
        .body["id"]
        .as_u64()
        .unwrap();
    let r = request(
        &addr,
        "GET",
        &format!("/versions/{v2}/collections/users/records"),
        None,
    );
    let recs = r.body["records"].as_array().unwrap();
    assert_eq!(recs.len(), 2);
    let u1 = recs.iter().find(|rec| rec["id"] == "u1").unwrap();
    assert_eq!(u1["v"], 100);
}

