66	fn request(addr: &str, method: &str, path: &str, body: Option<&str>) -> RawResponse {
67	    let mut stream = TcpStream::connect(addr).unwrap();
68	    let mut req = format!("{method} {path} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n");
69	    if let Some(b) = body {
70	        req.push_str("Content-Type: application/json\r\n");
71	        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
72	    }
73	    req.push_str("\r\n");
74	    if let Some(b) = body {
75	        req.push_str(b);
76	    }
77	    stream.write_all(req.as_bytes()).unwrap();
78	    let mut raw = String::new();
79	    stream.read_to_string(&mut raw).unwrap();
80	    let split = raw.find("\r\n\r\n").unwrap();
81	    let head = &raw[..split];
82	    let text = &raw[split + 4..];
83	    let status: u16 = head
84	        .lines()
85	        .next()
86	        .unwrap()
87	        .split_whitespace()
88	        .nth(1)
89	        .unwrap()
90	        .parse()
91	        .unwrap();
92	    RawResponse {
93	        status,
94	        body: serde_json::from_str(text.trim()).unwrap_or(Value::Null),
95	    }
96	}
